 33	/// One enclosing split/fuse dyad hides the whole walk. All twelve marks appear;
 34	/// the work opcodes sit between ∈ and ∋ and surface as the single factor output.
 35	pub const NESTED_WORD: &str = "⊢∈≻⋈⊤≻⋈⊥≺⋈⊞⊙∋⊡⊣";
 36	
 37	/// vox closure verdict for the nested word: T = closes with work inside the
 38	/// dyad (the computation is hidden and surfaces as one output), B = fork left
 39	/// open, F = ill-typed, N = no work inside.
 40	pub fn vox_verdict() -> char {
 41	    let chars: Vec<char> = NESTED_WORD.chars().collect();
 42	    crate::vox::verdict(&chars)
 43	}
 44	
 45	fn pow2(k: usize) -> WordTape {
 46	    WordTape::one_at(k)
 47	}
 48	
 49	/// Newton inverse of an odd `a` modulo 2^m, entirely on the word. Precision
 50	/// doubles each pass, so ceil(log2 m)+3 passes are ample.
 51	fn inv_mod_pow2(a: &WordTape, m: usize) -> WordTape {
 52	    let two = WordTape::from_small(2);
 53	    let full = pow2(m);
 54	    let mut x = WordTape::one();
 55	    let iters = (m as u32).ilog2() as usize + 3;
 56	    for _ in 0..iters {
 57	        let ax = a.mul(&x).truncate(m);
 58	        // t = (2 - ax) mod 2^m. ax is odd (a, x odd), so ax != 0 and ax != 2.
 59	        let t = if ax.ge(&two) {
 60	            let d = ax.sub(&two).unwrap();
 61	            full.sub(&d).unwrap()
 62	        } else {
 63	            two.sub(&ax).unwrap()
 64	        };
 65	        x = x.mul(&t).truncate(m);
 66	    }
 67	    x
 68	}
 69	
 70	/// The closure-height walk. Walks the four 2-adic unit cosets {1,3,-1,-3};
 71	/// at each position P the partner Q = N·P^{-1} mod 2^m is tracked by one
 72	/// multiply, and P·Q == N (exactly, not mod 2^m) is the closure test. Length
 73	/// 2^(m-1) total, independent of the prime gap.
 74	pub fn factor(n: &BigUint, m: usize) -> Option<BigUint> {
 75	    if m < 4 { return None; }
 76	    let n_wt = WordTape::from_biguint(n);
 77	    let nine = WordTape::from_small(9);
 78	    let inv9 = inv_mod_pow2(&nine, m);
 79	    let nm = n_wt.truncate(m);
 80	    let lead = pow2(m - 1);
 81	    let mask = pow2(m).sub(&WordTape::one()).unwrap();
 82	    let m3 = mask.sub(&WordTape::from_small(2)).unwrap();
 83	    let reps: [WordTape; 4] = [
 84	        WordTape::from_small(1),
 85	        WordTape::from_small(3),
 86	        mask,
 87	        m3,
 88	    ];
 89	    let positions = 1usize.checked_shl((m - 3) as u32).unwrap_or(usize::MAX);
 90	    for s in reps.iter() {
 91	        let mut p: WordTape = s.truncate(m);
 92	        let mut q: WordTape = nm.mul(&inv_mod_pow2(&p, m)).truncate(m);
 93	        for _ in 0..positions {
 94	            if p.ge(&lead) && q.ge(&lead) && p.mul(&q) == n_wt {
 95	                let f = if q.ge(&p) { &p } else { &q };
 96	                return Some(f.to_biguint());
 97	            }
 98	            p = p.mul(&nine).truncate(m);
 99	            q = q.mul(&inv9).truncate(m);
100	        }
101	    }
102	    None
103	}
