105	/// REPL entry: `closure_nested <n> <m>`. n is the composite (decimal), m the
106	/// factor bit width. Reports the vox verdict on the nested word and the factor.
107	pub fn repl_closure_nested(args: &[&str]) -> String {
108	    if args.len() >= 2 && args[0] == "wide" {
109	        let n: BigUint = match args[1].parse() {
110	            Ok(x) => x,
111	            Err(_) => return format!("closure_nested wide <n> <m> [max_steps]: bad n"),
112	        };
113	        let m: usize = match args.get(2).and_then(|s| s.parse().ok()) {
114	            Some(x) => x,
115	            None => return format!("closure_nested wide <n> <m> [max_steps]: bad m"),
116	        };
117	        let ms: usize = match args.get(3).and_then(|s| s.parse().ok()) {
118	            Some(x) => x,
119	            None => 1usize.checked_shl((m.saturating_sub(3)) as u32).unwrap_or(usize::MAX),
120	        };
121	        return match closure_height_walk(&n, m, ms) {
122	            Some(f) => {
123	                let cof = &n / &f;
124	                let ok = if &f * &cof == n { "verified" } else { "MISMATCH" };
125	                format!("wide closure-height walk (no m<=60 floor): N = {} x {} ({})  [m={}, {} steps, arbitrary precision]",
126	                    f, cof, ok, m, ms)
127	            }
128	            None => format!("wide closure-height walk: no factor at m={} within {} steps (m>=4; position count is O(2^m))", m, ms),
129	        };
130	    }
131	    if args.len() >= 2 && args[0] == "extract" {
132	        let n: BigUint = match args[1].parse() {
133	            Ok(x) => x,
134	            Err(_) => return format!("closure_nested extract <n> <m>: bad n"),
135	        };
136	        let m: usize = match args.get(2).and_then(|s| s.parse().ok()) {
137	            Some(x) => x,
138	            None => return format!("closure_nested extract <n> <m>: bad m"),
139	        };
140	        return factor_symbolic(&n, m);
141	    }
142	    if args.len() >= 2 && args[0] == "ambient" {
143	        let n: BigUint = match args[1].parse() {
144	            Ok(x) => x,
145	            Err(_) => return format!("closure_nested ambient <n> <m>: bad n"),
146	        };
147	        let m: usize = match args.get(2).and_then(|s| s.parse().ok()) {
148	            Some(x) => x,
149	            None => return format!("closure_nested ambient <n> <m>: bad m"),
150	        };
151	        return match factor_ambient(&n, m) {
152	            Some((f, report)) => format!(
153	                "ambient closure: N = {} x {} (digit channel verified)\n{}",
154	                f, &n / &f, report),
155	            None => format!("ambient closure: no factor at m={} (or m<4)", m),
156	        };
157	    }
158	    if args.len() >= 2 && args[0] == "numeral" {
159	        let n: BigUint = match args[1].parse() {
160	            Ok(x) => x,
161	            Err(_) => return format!("closure_nested numeral <n>: bad n"),
162	        };
163	        return format!("numeral word: {}", numeral_word(&n));
164	    }
165	    if args.len() >= 2 && args[0] == "word" {
166	        let m: usize = match args[1].parse() {
167	            Ok(x) => x,
168	            Err(_) => return format!("closure_nested word <m>: bad m"),
169	        };
170	        return nested_signature(m);
171	    }
172	    if args.len() < 2 {
173	        return format!("closure_nested <n> <m>  -- n decimal composite, m factor bit width; new nested-IMASM build");
174	    }
175	    let n: BigUint = match args[0].parse() {
176	        Ok(x) => x,
177	        Err(_) => return format!("closure_nested: bad n"),
178	    };
179	    let m: usize = match args[1].parse() {
180	        Ok(x) => x,
181	        Err(_) => return format!("closure_nested: bad m"),
182	    };
183	    let verdict = vox_verdict();
184	    let f = factor_numeral(&n, m);
185	    if m >= 4 && f > BigUint::one() && f < n && &n % &f == BigUint::zero() {
186	        let cof = &n / &f;
187	        let ok = if &f * &cof == n { "verified" } else { "MISMATCH" };
188	        format!("vox verdict {}  word {}\nclosure_nested: N = {} x {}  ({})  [{} positions, word-walk]",
189	            verdict, NESTED_WORD, f, cof, ok, 1usize << (m - 1))
190	    } else {
191	        format!("vox verdict {}  word {}\nclosure_nested: surfaced numeral {} (re-encoded from symbols at width m={})",
192	            verdict, NESTED_WORD, f, m)
193	    }
194	}
