196	/// The properly nested word for band width m: all (m-3) splits stacked before
197	/// the work (δ before δ) and all (m-3) fuses stacked after the reversal (μ after
198	/// μ). The nesting depth d = m-3 symbolizes the 2^(m-3) unit-group orbit
199	/// logarithmically; the count banked in the frame stack survives every AREV and
200	/// the outer fuse restores it as one output.
201	pub fn nested_word(m: usize) -> String {
202	    let d = m.saturating_sub(3);
203	    let mut w = String::from("⊢");
204	    for _ in 0..d { w.push('∈'); }
205	    w.push_str("≻⋈⊤≻⋈⊥≺⋈⊞⊙");
206	    for _ in 0..d { w.push('∋'); }
207	    w.push_str("⊡⊣");
208	    w
209	}
210	
211	/// The banked signature of the nested word, read by the same instrument the
212	/// kernel uses. Depth-invariant once nested: deposits, live clears and the
213	/// holds() verdict do not grow with m, so the symbolic cost is O(word length)
214	/// = O(m), not O(2^m).
215	pub fn nested_signature(m: usize) -> String {
216	    let word = nested_word(m);
217	    let d = m.saturating_sub(3);
218	    match lattice_flow::banked_walk(&word) {
219	        Some(b) => format!(
220	            "nested depth={} length={} deposits={} live_clears={} exposed={} holds={}\n  word {}",
221	            d, word.chars().count(), b.deposits, b.live_clears,
222	            b.exposed.len(), b.holds(), word),
223	        None => format!("nested depth={} unreadable", d),
224	    }
225	}
