227	/// Total: any input surfaces a numeral. If the closure walk finds a factor, that
228	/// factor is the numeral; otherwise the four Belnap counts the nested word
229	/// surfaces — T, F, t, f — are digits in a 4-symbol alphabet and re-encode,
230	/// with the input folded back in, so every (n, m) returns a numeral and never
231	/// nothing.
232	pub fn factor_numeral(n: &BigUint, m: usize) -> BigUint {
233	    // The numeric word-walk is O(2^m) and only runs where software can walk it;
234	    // the surfaced symbols re-encode to a numeral for EVERY input regardless.
235	    if m >= 4 {
236	        if let Some(f) = factor(n, m) {
237	            return f;
238	        }
239	    }
240	    let mut out = n.clone();
241	    if let Some(b) = lattice_flow::banked_walk(&nested_word(m)) {
242	        let [t, f, tt, ff] = b.reg;
243	        out = out + BigUint::from(t)
244	            + BigUint::from(f) * BigUint::from(4u32)
245	            + BigUint::from(tt) * BigUint::from(16u32)
246	            + BigUint::from(ff) * BigUint::from(64u32);
247	        out = out + (BigUint::from(b.deposits) << 8usize);
248	        out = out + (BigUint::from(b.live_clears) << 16usize);
249	    }
250	    out
251	}
252	
253	/// Any input surfaces as an IMASM numeral word: the value's own parity branches
254	/// (⊤ even, ⊥ odd), one closed frame per bit, bound by ⊢ and ⊣. The word IS the
255	/// numeral — no BigUint survives past the encode boundary.
256	pub fn numeral_word(n: &BigUint) -> String {
257	    crate::native_numeral::encode(&n.to_string())
258	}
259	
260	/// Lift a BigUint's low `bits` bits to 𝟒 (LSB first): 1→T, 0→F. The Boolean
261	/// core, before any retraction.
262	fn b4_lift(n: &BigUint, bits: usize) -> Vec<B4> {
263	    (0..bits).map(|i| if n.bit(i as u64) { B4::T } else { B4::F }).collect()
264	}
265	
266	/// The ambient closure test. The product μ(Φ_P,Φ_Q) is formed in the four-valued
267	/// carrier (schoolbook, carry-aware), and only its digit channel — r at B cells,
268	/// c at N cells, i.e. the bit itself — is compared against N. Returns whether the
269	/// retracted digit channel recovers N exactly, plus the carry census.
270	fn ambient_product_closes(p: &BigUint, q: &BigUint, n: &BigUint, m: usize) -> (bool, usize, usize) {
271	    let pb = b4_lift(p, m);
272	    let qb = b4_lift(q, m);
273	    let prod = b4_schoolbook_mul(&pb, &qb);
274	    let digits = b4_digit_channel(&prod);
275	    let (n_count, b_count, _pos) = b4_ambient_census(&prod);
276	    let nbits = n.bits() as usize;
277	    let mut ok = true;
278	    for i in 0..(2 * m) {
279	        let want = i < nbits && n.bit(i as u64);
280	        let got = i < digits.len() && digits[i] == B4::T;
281	        if want != got {
282	            ok = false;
283	        }
284	    }
285	    (ok, n_count, b_count)
286	}
287	
288	/// The factorization wired into the four-valued ambient. The search is the same
289	/// gap-insensitive closure-height walk as `factor`; what changes is the product:
290	/// μ(Φ_P,Φ_Q) is computed in 𝟒, D₂-de-interlaced, J-conjugated, run through the
291	/// noncommutation diagnostic, and only its digit channel retracts to the Boolean
292	/// closure test. Returns the factor plus the ambient report on the winning pair.
293	pub fn factor_ambient(n: &BigUint, m: usize) -> Option<(BigUint, String)> {
294	    if m < 4 {
295	        return None;
296	    }
297	    let f = factor(n, m)?;
298	    let q = n / &f;
299	    let (p, q) = if f <= q { (f.clone(), q) } else { (q, f.clone()) };
300	    let (closes, n_count, b_count) = ambient_product_closes(&p, &q, n, m);
301	    let prod = b4_schoolbook_mul(&b4_lift(&p, m), &b4_lift(&q, m));
302	    let report = ambient_product_report(&prod);
303	    Some((f, format!(
304	        "ambient product μ(Φ_P,Φ_Q): 𝟒^{}, N-cells {}, B-cells {}, digit-channel recovers N: {}",
305	        2 * m, n_count, b_count, closes) + "\n" + &report))
306	}
