352	/// Newton inverse of an odd `a` modulo 2^m, arbitrary precision. Precision
353	/// doubles each pass, so ceil(log2 m)+3 passes are ample. This is the same
354	/// Hensel lift as `inv_mod_pow2`, lifted off WordTape onto BigUint so the
355	/// floorless walk never touches a fixed-width limb.
356	fn big_inv_pow2(a: &BigUint, m: usize) -> BigUint {
357	    let two = BigUint::from(2u32);
358	    let two_m = BigUint::one() << m;
359	    let mask = &two_m - BigUint::one();
360	    let mut x = BigUint::one();
361	    let iters = (m as u32).ilog2() as usize + 3;
362	    for _ in 0..iters {
363	        let ax = (a * &x) & &mask;
364	        // t = (2 - ax) mod 2^m. ax is odd, so ax != 0 and ax != 2.
365	        let t = if ax == BigUint::one() { BigUint::one() } else { &two_m - (ax - &two) };
366	        x = (x * t) & &mask;
367	    }
368	    x
369	}
