 70	/// The closure-height walk. Walks the four 2-adic unit cosets {1,3,-1,-3};
 71	/// at each position P the partner Q = N·P^{-1} mod 2^m is tracked by one
 72	/// multiply, and P·Q == N (exactly, not mod 2^m) is the closure test. Length
 73	/// 2^(m-1) total, independent of the prime gap.
 74	pub fn factor(n: &BigUint, m: usize) -> Option<BigUint> {
 75	    if m < 4 { return None; }
 76	    let n_wt = WordTape::from_biguint(n);
 77	    let nine = WordTape::from_small(9);
 78	    let inv9 = inv_mod_pow2(&nine, m);
 79	    let nm = n_wt.truncate(m);
 80	    let lead = pow2(m - 1);
 81	    let mask = pow2(m).sub(&WordTape::one()).unwrap();
 82	    let m3 = mask.sub(&WordTape::from_small(2)).unwrap();
 83	    let reps: [WordTape; 4] = [
 84	        WordTape::from_small(1),
 85	        WordTape::from_small(3),
 86	        mask,
 87	        m3,
 88	    ];
 89	    let positions = 1usize.checked_shl((m - 3) as u32).unwrap_or(usize::MAX);
 90	    for s in reps.iter() {
 91	        let mut p: WordTape = s.truncate(m);
 92	        let mut q: WordTape = nm.mul(&inv_mod_pow2(&p, m)).truncate(m);
 93	        for _ in 0..positions {
 94	            if p.ge(&lead) && q.ge(&lead) && p.mul(&q) == n_wt {
 95	                let f = if q.ge(&p) { &p } else { &q };
 96	                return Some(f.to_biguint());
 97	            }
 98	            p = p.mul(&nine).truncate(m);
 99	            q = q.mul(&inv9).truncate(m);
100	        }
101	    }
102	    None
103	}
