196	/// The properly nested word for band width m: all (m-3) splits stacked before
197	/// the work (δ before δ) and all (m-3) fuses stacked after the reversal (μ after
198	/// μ). The nesting depth d = m-3 symbolizes the 2^(m-3) unit-group orbit
199	/// logarithmically; the count banked in the frame stack survives every AREV and
200	/// the outer fuse restores it as one output.
201	pub fn nested_word(m: usize) -> String {
202	    let d = m.saturating_sub(3);
203	    let mut w = String::from("⊢");
204	    for _ in 0..d { w.push('∈'); }
205	    w.push_str("≻⋈⊤≻⋈⊥≺⋈⊞⊙");
206	    for _ in 0..d { w.push('∋'); }
207	    w.push_str("⊡⊣");
208	    w
209	}
