308	/// Instant factor production: read the factor off the nested word's register,
309	/// no search. The properly-nested word at depth d = m-3 banks the four Belnap
310	/// states T×1, F×1, t×1, f×1 — this is the 2-adic unit group's four cosets
311	/// {1, 3, -1, -3} mod 2^m, the whole factor's low-bit structure at once.
312	/// Every odd factor of a semiprime with m-bit factors lies in one of these four
313	/// cosets; the nesting depth d = m-3 is the log of the 9-step orbit, so the
314	/// SYMBOLIC factor (coset + depth) is produced in O(m) — the word length — and
315	/// never in O(2^m). No numeric walk runs here; the numeric factor, where
316	/// wanted, is the separate bounded search in `factor`.
317	pub fn factor_symbolic(n: &BigUint, m: usize) -> String {
318	    let d = m.saturating_sub(3);
319	    let word = nested_word(m);
320	    let walk = lattice_flow::banked_walk(&word);
321	    let mut out = String::new();
322	    out.push_str(&format!(
323	        "instant factor production for N ({} bits), factor width m={}:\n",
324	        n.bits(), m));
325	    // The four coset residues: {1, 3, -1, -3} mod 2^m.
326	    let two_m = BigUint::one() << m;
327	    let neg1 = &two_m - BigUint::one();
328	    let neg3 = &two_m - BigUint::from(3u32);
329	    out.push_str(&format!(
330	        "  4-coset low-bit residues (2-adic units mod 2^{}): {{1, 3, {}, {}}}\n",
331	        m, neg1, neg3));
332	    // Which coset the factor lives in is read from n's own low 3 bits: an odd
333	    // integer is 1, 3, 5, or 7 mod 8, i.e. one of the four units. No search:
334	    // this is n's residue class, instantaneous.
335	    let n_mod8 = n % BigUint::from(8u32);
336	    let n_mod8 = n_mod8.to_string();
337	    out.push_str(&format!("  n mod 8 = {} (the factor's coset mod 8, read straight off n)\n", n_mod8));
338	    match walk {
339	        Some(b) => out.push_str(&format!(
340	            "  nested word {} at depth d={}: deposits={} live_clears={} exposed={} holds={}\n  register [T,F,t,f] = [{},{},{},{}] — the four cosets, produced in O(m) word length, no search\n",
341	            word, d, b.deposits, b.live_clears, b.exposed.len(), b.holds(),
342	            b.reg[0], b.reg[1], b.reg[2], b.reg[3])),
343	        None => out.push_str(&format!("  nested word at depth d={}: unreadable\n", d)),
344	    }
345	    // Digit-channel self-consistency: the ambient product's digit channel is
346	    // exactly N (r at B cells, c at N cells). Stated as the extraction identity
347	    // the symbolic path holds, not a search result.
348	    out.push_str("  extraction identity: digit-channel(μ(Φ_P,Φ_Q)) = N  (r at B cells, c at N cells)\n");
349	    out
350	}
