1	//! Lattice cycling and weight flow over an IMASM word, in the kernel.
2	//!
3	//! A word is a ring and ROTAT is the cyclic shift, so every rotation is the
4	//! same object. The verdict and the topology hold across the whole orbit; the
5	//! FINAL REGISTER does not. That makes the phase the only handle on where a
6	//! word comes to rest, and `cycle_report` prints the map from cut to landing
7	//! register so the handle can be read rather than guessed.
8	//!
9	//! `weight_report` answers the other half. The trilattice machine holds each
10	//! open fork as a set and closes it with a union, so a finished walk knows
11	//! WHICH base values were touched and nothing else: not how many times, not by
12	//! which arm, not whether a value reached the end or was destroyed and restored
13	//! on the way. This walks the same rules while counting, so the movement is
14	//! visible. Weight banked in a frame survives a clear that empties the
15	//! register; weight left in the open does not.
16	//!
17	//! The lift of OR to weights is MAX, not sum. Adding would count each deposit
18	//! twice, once landing in the register and again when its frame closed; under
19	//! max the fuse RESTORES what a clear destroyed and leaves the rest alone, and
20	//! at weights zero and one the accounting reduces to the set semantics exactly.
21	//!
22	//! Two movements carry no weight at all and are reported because they are
23	//! otherwise invisible in a final register:
24	//!
25	//!   SEED   AFWD and IMSCRIB put T into an empty register directly, so a walk
26	//!          can land in T having carried nothing
27	//!   INERT  after IFIX every token but IFIX and IMSCRIB is a no-op, so a word
28	//!          can be almost entirely inert
29	
30	
31	/// The reports were written straight to the kernel console with `sprintln!`,
32	/// which is why the host `ask` binary could not use them. They build a String
33	/// now and the kernel prints it; `sw!` is the one-line shim that made the move
34	/// mechanical rather than a rewrite.
35	macro_rules! sw {
36	    ($o:expr) => {{ $o.push('\n'); }};
37	    ($o:expr, $($t:tt)*) => {{
38	        use core::fmt::Write as _;
39	        let _ = write!($o, $($t)*);
40	        $o.push('\n');
41	    }};
42	}
43	
44	use alloc::string::String;
45	use alloc::vec::Vec;
46	use alloc::format;
47	use crate::imasm16_3::{parse_glyph_word, run_word_register, tri_ancestral_verdict, Token16_3};
48	
49	
50	/// Bring a word onto the current alphabet before the core reads it.
51	///
52	/// The retired spellings are still in every stored word and in anything copied
53	/// out of an older report, and the tensor forms turn up where a fork and a fuse
54	/// were written as ⊗ and ⊕. Translating is what lets those load; dropping them
55	/// would read the word as shorter than it is and change its verdict.
56	pub fn normalize(word: &str) -> String {
57	    let mut out = String::new();
58	    for c in word.chars() {
59	        match c {
60	            '◇' | '⊗' => out.push('∈'),
61	            '●' | '⊕' => out.push('∋'),
62	            '=' | '═' => out.push('⋈'),
63	            '+' => out.push('⊤'),
64	            '×' => out.push('⊥'),
65	            '¬' => out.push('⊡'),
66	            c if c.is_whitespace() => {}
67	            c => out.push(c),
68	        }
69	    }
70	    out
71	}
72	
73	fn render(steps: &[Token16_3]) -> String {
74	    let mut s = String::new();
75	    for t in steps { s.push(t.glyph()); }
76	    s
77	}
78	
79	/// The landing register at every cut of the word's rotation orbit, in order
80	/// k=0..period. Separated from `cycle_report` the same way `banked_walk` sits
81	/// apart from `banked_report`: a caller that needs the verdict, not the
82	/// paragraph, walks the orbit once and reads the list.
83	pub fn cycle_landings(word: &str) -> Option<Vec<String>> {
84	    let steps = parse_glyph_word(&normalize(word));
85	    let n = steps.len();
86	    if n == 0 { return None; }
87	    let mut landings = Vec::with_capacity(n);
88	    for k in 0..n {
89	        let mut rot: Vec<Token16_3> = Vec::with_capacity(n);
90	        for i in 0..n { rot.push(steps[(i + k) % n]); }
91	        landings.push(run_word_register(&rot));
92	    }
93	    Some(landings)
94	}
95	
96	/// The tri-ancestral close condition (`imasm16_3::tri_ancestral_verdict`) on
97	/// the word AS A LOOP — the Grammar's own existing T/N/B/F verdict, not a
98	/// reduction invented on top of the register content. Pairing is cyclic
99	/// (every FSPLIT3 sought against every FFUSE3 around the ring, not linearly),
100	/// so this already reads the whole word in one call; it is not one cut
101	/// among many the way `cycle_landings`' entries are.
102	///
103	///   T — every fork pairs with a fuse around the cycle, and real work (a
104	///       WORK opcode) ran inside at least one paired region.
105	///   N — paired, but no work ran anywhere — void, verifies nothing.
106	///   B — a fork has no fuse to pair with around the cycle — left open.
107	///   F — a fuse has no fork to pair with — ill-typed.
108	pub fn tri_ancestral_word_verdict(word: &str) -> Option<char> {
109	    let steps = parse_glyph_word(&normalize(word));
110	    if steps.is_empty() { return None; }
111	    Some(tri_ancestral_verdict(&steps).0)
112	}
113	
114	pub fn cycle_report(word: &str) -> String {
115	    let mut out = String::new();
116	    let steps = parse_glyph_word(&normalize(word));
117	    let n = steps.len();
118	    if n == 0 {
119	        sw!(out, "  no IMASM glyphs in that word");
120	        return out;
121	    }
122	    sw!(out, "word   : {}   period {}", render(&steps), n);
123	    sw!(out, "   {:>3}  {:<6} {:<8} word", "k", "final", "verdict");
124	
125	    let mut finals: Vec<(String, usize)> = Vec::new();
126	    for k in 0..n {
127	        let mut rot: Vec<Token16_3> = Vec::with_capacity(n);
128	        for i in 0..n { rot.push(steps[(i + k) % n]); }
129	        let reg = run_word_register(&rot);
130	        let (v, _) = tri_ancestral_verdict(&rot);
131	        sw!(out, "   {:>3}  {:<6} {:<8} {}", k, reg, v, render(&rot));
132	        finals.push((reg, k));
133	    }
134	
135	    // The map the whole thing exists for: which cut lands you where.
136	    sw!(out, "");
137	    sw!(out, "  landing register by cut:");
138	    let mut seen: Vec<String> = Vec::new();
139	    for (reg, _) in finals.iter() {
140	        if !seen.iter().any(|s| s == reg) { seen.push(reg.clone()); }
141	    }
142	    for reg in seen.iter() {
143	        let mut ks = String::new();
144	        for (r, k) in finals.iter() {
145	            if r == reg {
146	                if !ks.is_empty() { ks.push_str(", "); }
147	                ks.push_str(&format!("{}", k));
148	            }
149	        }
150	        sw!(out, "    {:<6} at k = {}", reg, ks);
151	    }
152	    let distinct = seen.len();
153	    if distinct == 1 {
154	        sw!(out, "  final register is INVARIANT under ROTAT here");
155	    } else {
156	        sw!(out, "  final register is PHASE-BEARING: {} distinct landings", distinct);
157	    }
158	    out
159	}
160	
161	
162	/// FRAMES — which readings survive rotation and which are artifacts of the cut.
163	///
164	/// A word is a ring. We evaluate ONE cut of it and take what we see there for a
165	/// property of the word, but every rotation is the same object and every frame is
166	/// equally available to be read. So a reported quantity is one of two things, and
167	/// the report must say which:
168	///
169	///   INVARIANT   true of the word — it reads the same from every frame
170	///   FRAME-BOUND it reads the cut, not the word; quoting it without the frame is
171	///               quoting an accident of where the ring was opened
172	///
173	/// This walks the whole orbit and partitions the readings. Anything landing in the
174	/// second column is still real — it is just a fact about a frame, and the frame has
175	/// to travel with it.
176	pub fn frames_report(word: &str) -> String {
177	    let mut out = String::new();
178	    let steps = parse_glyph_word(&normalize(word));
179	    let n = steps.len();
180	    if n == 0 {
181	        sw!(out, "  no IMASM glyphs in that word");
182	        return out;
183	    }
184	    sw!(out, "word   : {}   period {}   ({} frames, all equally readable)", render(&steps), n, n);
185	
186	    let mut verdicts: Vec<char> = Vec::new();
187	    let mut finals: Vec<String> = Vec::new();
188	    let mut firsts: Vec<char> = Vec::new();
189	    for k in 0..n {
190	        let mut rot: Vec<Token16_3> = Vec::with_capacity(n);
191	        for i in 0..n { rot.push(steps[(i + k) % n]); }
192	        let (v, _) = tri_ancestral_verdict(&rot);
193	        verdicts.push(v);
194	        finals.push(run_word_register(&rot));
195	        firsts.push(rot[0].glyph());
196	    }
197	    let uniq_v = {
198	        let mut u: Vec<char> = Vec::new();
199	        for v in verdicts.iter() { if !u.contains(v) { u.push(*v); } }
200	        u
201	    };
202	    let uniq_f = {
203	        let mut u: Vec<String> = Vec::new();
204	        for f in finals.iter() { if !u.iter().any(|x| x == f) { u.push(f.clone()); } }
205	        u
206	    };
207	    let uniq_first = {
208	        let mut u: Vec<char> = Vec::new();
209	        for c in firsts.iter() { if !u.contains(c) { u.push(*c); } }
210	        u
211	    };
212	
213	    sw!(out, "");
214	    sw!(out, "  INVARIANT — true of the word, readable from any frame:");
215	    sw!(out, "    period                {}", n);
216	    sw!(out, "    glyph multiset        {} distinct over {} positions", {
217	        let mut u: Vec<char> = Vec::new();
218	        for t in steps.iter() { let g = t.glyph(); if !u.contains(&g) { u.push(g); } }
219	        u.len()
220	    }, n);
221	    if uniq_v.len() == 1 {
222	        sw!(out, "    verdict               {}", uniq_v[0]);
223	    }
224	    sw!(out, "    ring transitions      counted with the closing edge, so rotation cannot move them");
225	
226	    sw!(out, "");
227	    sw!(out, "  FRAME-BOUND — reads the cut, and must be quoted with it:");
228	    if uniq_v.len() > 1 {
229	        sw!(out, "    verdict               {} distinct over the orbit — NOT a property of the word", uniq_v.len());
230	    }
231	    sw!(out, "    final register        {} distinct landing(s)", uniq_f.len());
232	    for reg in uniq_f.iter() {
233	        let mut ks = String::new();
234	        for (k, f) in finals.iter().enumerate() {
235	            if f == reg {
236	                if !ks.is_empty() { ks.push_str(", "); }
237	                ks.push_str(&format!("{}", k));
238	            }
239	        }
240	        sw!(out, "      {:<6} at k = {}", reg, ks);
241	    }
242	    sw!(out, "    opening glyph         {} distinct — every frame opens on a different mark", uniq_first.len());
243	    sw!(out, "    absolute position     any row/tier/parity reading; one rotation moves every value");
244	
245	    sw!(out, "");
246	    if uniq_f.len() == 1 {
247	        sw!(out, "  This word is FRAME-FREE in its landing: every cut comes to rest in the same");
248	        sw!(out, "  register, so the evaluated frame carries no privilege over the others.");
249	    } else {
250	        sw!(out, "  This word is PHASE-BEARING: {} of its {} frames disagree about where it rests.", uniq_f.len(), n);
251	        sw!(out, "  The frame you evaluated is one of them and is not the word's own answer.");
252	    }
253	    out
254	}
255	
256	/// Opcode-to-opcode transitions counted ON THE RING.
257	///
258	/// A word is a cycle and ROTAT is the cyclic shift, so a word of length n has n
259	/// transitions, not n-1. The one a linear read drops is the wrap from the last
260	/// opcode back to the first, and in IMASM that is overwhelmingly TANCH -> VINIT:
261	/// the anchor returning to the source. Across k programs a linear read loses
262	/// exactly k such edges, and a table built without them can show a rule as
263	/// universal that the closing edges break.
264	pub fn transitions_report(word: &str) -> String {
265	    let mut out = String::new();
266	    let steps = parse_glyph_word(&normalize(word));
267	    let n = steps.len();
268	    if n == 0 { sw!(out, "  no IMASM glyphs in that word"); return out; }
269	    sw!(out, "word   : {}   length {}", render(&steps), n);
270	    sw!(out, "  ring transitions   : {}", n);
271	    sw!(out, "  linear would give  : {}   (drops the closing edge)", n - 1);
272	    sw!(out, "  closing edge       : {} -> {}",
273	              steps[n - 1].glyph(), steps[0].glyph());
274	    sw!(out, "");
275	    // count them, most frequent first, without allocating a map
276	    let mut seen: Vec<((char, char), u32)> = Vec::new();
277	    for i in 0..n {
278	        let key = (steps[i].glyph(), steps[(i + 1) % n].glyph());
279	        if let Some(e) = seen.iter_mut().find(|e| e.0 == key) { e.1 += 1; }
280	        else { seen.push((key, 1)); }
281	    }
282	    seen.sort_by(|a, b| b.1.cmp(&a.1));
283	    sw!(out, "  transitions:");
284	    for ((a, b), c) in seen.iter() {
285	        sw!(out, "    {} -> {}   {}", a, b, c);
286	    }
287	    sw!(out, "");
288	    sw!(out, "  Anything read from ABSOLUTE position on a ring measures the cut,");
289	    sw!(out, "  not the word: matrix rows, tetraktys tiers, odd against even.");
290	    sw!(out, "  One rotation moves every value into a different row.");
291	    out
292	}
293	
294	/// Was anything counted, then cleared with nothing banked behind it?
295	///
296	/// AREV empties the register and leaves open frames alone, so a result fused
297	/// back to depth zero is exposed to the next reversal, while the same result
298	/// held one level up survives it. A program that establishes something, then
299	/// reverses, then bounds must open the region that will HOLD the result before
300	/// the region that COMPUTES it, and close them in that order.
301	/// What the banking walk found. Separated from the printing so a caller can
302	/// test a word instead of reading about it -- `insert` sweeps hundreds of
303	/// candidates and needs the verdict, not the paragraph. One walk, two callers.
304	pub struct Banked {
305	    pub exposed: Vec<(usize, char, u32)>,
306	    pub live_clears: u32,
307	    pub deposits: u32,
308	    pub inert: u32,
309	    pub reg: [u32; 4],
310	}
311	
312	impl Banked {
313	    /// Held across every clear that actually fired. Vacuous words are not OK:
314	    /// nothing was ever at risk, so nothing was held.
315	    pub fn holds(&self) -> bool { self.exposed.is_empty() && self.live_clears > 0 }
316	    pub fn vacuous(&self) -> bool { self.exposed.is_empty() && self.live_clears == 0 }
317	}
318	
319	pub fn banked_walk(word: &str) -> Option<Banked> {
320	    let steps = parse_glyph_word(&normalize(word));
321	    if steps.is_empty() { return None; }
322	    let mut reg = [0u32; 4];
323	    let mut frames: Vec<[u32; 4]> = Vec::new();
324	    let mut fixed = false;
325	    let mut exposed: Vec<(usize, char, u32)> = Vec::new();
326	    let mut live_clears = 0u32;
327	    let mut inert = 0u32;
328	    let mut deposits = 0u32;
329	
330	    for (i, t) in steps.iter().enumerate() {
331	        if fixed && !matches!(t, Token16_3::Ifix | Token16_3::Imscrib) { inert += 1; continue; }
332	        match t {
333	            Token16_3::Fsplit3 => frames.push([0; 4]),
334	            Token16_3::Ffuse3 => {
335	                if let Some(closed) = frames.pop() {
336	                    for j in 0..4 {
337	                        if closed[j] > reg[j] { reg[j] = closed[j]; }
338	                        if let Some(o) = frames.last_mut() {
339	                            if closed[j] > o[j] { o[j] = closed[j]; }
340	                        }
341	                    }
342	                }
343	            }
344	            Token16_3::Arev | Token16_3::Vinit => {
345	                let lost: u32 = reg.iter().sum();
346	                let banked: u32 = frames.iter().map(|f| f.iter().sum::<u32>()).sum();
347	                if lost > 0 {
348	                    live_clears += 1;
349	                    if banked == 0 { exposed.push((i + 1, t.glyph(), lost)); }
350	                }
351	                reg = [0; 4];
352	                if matches!(t, Token16_3::Vinit) { frames.clear(); }
353	            }
354	            Token16_3::Ifix => fixed = true,
355	            _ => {
356	                let touched: &[usize] = match t {
357	                    Token16_3::Evalt => &[0],
358	                    Token16_3::Evalf => &[1],
359	                    Token16_3::Evali => &[2, 3],
360	                    _ => &[],
361	                };
362	                if !touched.is_empty() { deposits += 1; }
363	                for &j in touched {
364	                    reg[j] += 1;
365	                    if let Some(f) = frames.last_mut() { f[j] += 1; }
366	                }
367	            }
368	        }
369	    }
370	
371	    Some(Banked { exposed, live_clears, deposits, inert, reg })
372	}
373	
374	pub fn banked_report(word: &str) -> String {
375	    let mut out = String::new();
376	    let steps = parse_glyph_word(&normalize(word));
377	    let b = match banked_walk(word) {
378	        Some(b) => b,
379	        None => { sw!(out, "  no IMASM glyphs in that word"); return out; }
380	    };
381	    let (exposed, live_clears, deposits, inert, reg) =
382	        (b.exposed, b.live_clears, b.deposits, b.inert, b.reg);
383	
384	    sw!(out, "word   : {}", render(&steps));
385	    if exposed.is_empty() && live_clears == 0 {
386	        // Passing because nothing was ever at risk is not the same as passing
387	        // because the frame held.
388	        sw!(out, "  VACUOUS — no clear ever fired against a live register");
389	        sw!(out, "    {} deposit(s), {} step(s) inert after a fixation", deposits, inert);
390	    } else if exposed.is_empty() {
391	        sw!(out, "  OK — weight survived {} live clear(s) by being banked", live_clears);
392	        // The second, independent fact. Banking asks whether a frame was open
393	        // at the clear; surplus asks where the splits fell between deposits of
394	        // the same value. A word can bank correctly and still lose a count.
395	        let mut surplus = 0u32;
396	        for j in 0..4 { if reg[j] > 1 { surplus += reg[j] - 1; } }
397	        if surplus > 0 {
398	            sw!(out, "    up to {} unit(s) of repeat deposit may be flattened by a", surplus);
399	            sw!(out, "    fold between sibling regions: the fold keeps the larger,");
400	            sw!(out, "    not the sum. Deposits in ONE region keep both.");
401	        }
402	    } else {
403	        let total: u32 = exposed.iter().map(|e| e.2).sum();
404	        sw!(out, "  {} unit(s) cleared with nothing banked behind them:", total);
405	        for (step, g, w) in exposed.iter() {
406	            sw!(out, "    step {} {} cleared {} with nothing behind it", step, g, w);
407	        }
408	        sw!(out, "  open the region that HOLDS the result before the region that");
409	        sw!(out, "  COMPUTES it, and close them in that order.");
410	    }
411	    out
412	}
413	
414	/// A candidate must hold on THREE different instruments, not two.
415	/// `banked_walk` asks whether weight cleared in the open. `tri_ancestral_word_verdict`
416	/// asks whether the fork/fuse pairing closes over real work. Neither of
417	/// those asks whether the wiring itself is legal -- `check::word_verdict`'s
418	/// `Graph::validate()` does, and a candidate can pass the first two while
419	/// failing it. Caught live on gpu_native_build_of_momonados's own repaired
420	/// word: inserting `⊢` (VINIT, zero in-arity by contract) between `⊞` and
421	/// `∋` fixed the fork/fuse count for tri-ancestral, but the chain gives that
422	/// node an in-edge from `⊞` regardless, which `validate()` flags as
423	/// "in-degree 1 > arity_in 0" -- a real grammar violation the first two
424	/// instruments cannot see, because neither of them asks about arity.
425	/// `insert_report`/`repair_count` used to accept that candidate as holding.
426	/// A closure carrying `⊞` legitimately reads B on `check` (paradox held,
427	/// not a clean T) -- that is not a failure here, only F (validate() non-empty)
428	/// disqualifies a candidate.
429	pub fn candidate_holds(cand: &str) -> bool {
430	    match banked_walk(cand) {
431	        Some(b) if b.holds() => {}
432	        _ => return false,
433	    }
434	    if tri_ancestral_word_verdict(cand) != Some('T') {
435	        return false;
436	    }
437	    let tokens: Option<Vec<crate::classic::Token>> = cand
438	        .chars()
439	        .map(|c| {
440	            let mut buf = [0u8; 4];
441	            crate::classic::Token::parse(c.encode_utf8(&mut buf))
442	        })
443	        .collect();
444	    match tokens {
445	        Some(toks) => {
446	            let pairs = crate::check::match_pairs(&toks);
447	            let g = crate::check::from_sequence(&toks, &pairs);
448	            g.validate().is_empty()
449	        }
450	        None => false,
451	    }
452	}
453	
454	/// Every single-glyph insertion that turns an exposed word into one that
455	/// both holds (banked) and still closes (tri-ancestral T). A word that
456	/// loses weight is not usually rewritten; it is repaired, and the repair
457	/// is almost always one glyph in the right place. Rather than reason
458	/// about which, this walks all twelve glyphs at every position and reports
459	/// the ones that pass both checks. The search is small -- twelve times
460	/// length-plus-one -- and exact, so there is nothing to infer.
461	pub fn insert_report(word: &str) -> String {
462	    let mut out = String::new();
463	    let steps = parse_glyph_word(&normalize(word));
464	    if steps.is_empty() { sw!(out, "  no IMASM glyphs in that word"); return out; }
465	    let base = render(&steps);
466	    let n = steps.len();
467	
468	    sw!(out, "word   : {}   length {}", base, n);
469	    match banked_walk(&base) {
470	        Some(b) if b.holds()   => { sw!(out, "  already holds — nothing to repair"); return out; }
471	        Some(b) if b.vacuous() => sw!(out, "  vacuous: no clear ever fired, so nothing is at risk"),
472	        Some(b) => {
473	            let lost: u32 = b.exposed.iter().map(|e| e.2).sum();
474	            sw!(out, "  exposed: {} unit(s) cleared with nothing banked", lost);
475	        }
476	        None => return out,
477	    }
478	
479	    let glyphs = ['⊢', '⊙', '∈', '∋', '⊤', '⊥', '≻', '≺', '⋈', '⊞', '⊡', '⊣'];
480	    let chars: Vec<char> = base.chars().collect();
481	
482	    // Distinct words, not distinct sites. Inserting a glyph beside an identical
483	    // one yields the same word from two positions, and counting both would
484	    // report a repair twice and overstate how many ways out there are.
485	    let mut seen: Vec<String> = Vec::new();
486	    let mut tried = 0u32;
487	
488	    sw!(out, "  insertions that hold:");
489	    for pos in 0..=n {
490	        for g in glyphs.iter() {
491	            let mut cand = String::new();
492	            for (k, c) in chars.iter().enumerate() {
493	                if k == pos { cand.push(*g); }
494	                cand.push(*c);
495	            }
496	            if pos == n { cand.push(*g); }
497	            if seen.iter().any(|w| w == &cand) { continue; }
498	            tried += 1;
499	            if candidate_holds(&cand) {
500	                sw!(out, "    {} at {:>2}   {}", g, pos, cand);
501	                seen.push(cand);
502	            }
503	        }
504	    }
505	    let found = seen.len();
506	    if found == 0 {
507	        sw!(out, "    none — no single glyph repairs this word without breaking tri-ancestral closure");
508	    } else {
509	        sw!(out, "  {} distinct word(s) hold (banked AND tri-ancestral T), of {} tried", found, tried);
510	    }
511	    out
512	}
513	
514	/// How many distinct one-glyph insertions make `base` hold, without printing.
515	pub fn repair_count(base: &str) -> usize {
516	    let glyphs = ['⊢', '⊙', '∈', '∋', '⊤', '⊥', '≻', '≺', '⋈', '⊞', '⊡', '⊣'];
517	    let chars: Vec<char> = base.chars().collect();
518	    let n = chars.len();
519	    let mut seen: Vec<String> = Vec::new();
520	    for pos in 0..=n {
521	        for g in glyphs.iter() {
522	            let mut cand = String::new();
523	            for (k, c) in chars.iter().enumerate() {
524	                if k == pos { cand.push(*g); }
525	                cand.push(*c);
526	            }
527	            if pos == n { cand.push(*g); }
528	            if seen.iter().any(|w| w == &cand) { continue; }
529	            if candidate_holds(&cand) { seen.push(cand); }
530	        }
531	    }
532	    seen.len()
533	}
534	
535	
536	/// Count what the union throws away.
537	pub fn weight_report(word: &str) -> String {
538	    let mut out = String::new();
539	    let steps = parse_glyph_word(&normalize(word));
540	    if steps.is_empty() {
541	        sw!(out, "  no IMASM glyphs in that word");
542	        return out;
543	    }
544	    sw!(out, "word   : {}", render(&steps));
545	
546	    // Base values are indexed T, F, t, f throughout.
547	    const NAMES: [&str; 4] = ["T", "F", "t", "f"];
548	    let mut reg = [0u32; 4];
549	    let mut frames: Vec<[u32; 4]> = Vec::new();
550	    let (mut deposits, mut cleared, mut restored, mut seeded, mut inert) =
551	        (0u32, 0u32, 0u32, 0u32, 0u32);
552	    let mut fixed = false;
553	    let mut nonempty = false;
554	
555	    sw!(out, "  movement:");
556	    for (i, t) in steps.iter().enumerate() {
557	        let step = i + 1;
558	        let g = t.glyph();
559	
560	        // The machine returns early once IFIX has fired: everything but IFIX
561	        // and IMSCRIB is inert. Counting a movement without the same guard
562	        // reports clears and fuses that never happened.
563	        if fixed && !matches!(t, Token16_3::Ifix | Token16_3::Imscrib) {
564	            inert += 1;
565	            continue;
566	        }
567	
568	        match t {
569	            Token16_3::Fsplit3 => {
570	                frames.push([0; 4]);
571	                sw!(out, "   {:>3} {}  open frame at depth {}", step, g, frames.len());
572	            }
573	            Token16_3::Ffuse3 => {
574	                if let Some(closed) = frames.pop() {
575	                    let mut got = 0u32;
576	                    for j in 0..4 {
577	                        if closed[j] > reg[j] { got += closed[j] - reg[j]; reg[j] = closed[j]; }
578	                        if let Some(outer) = frames.last_mut() {
579	                            if closed[j] > outer[j] { outer[j] = closed[j]; }
580	                        }
581	                    }
582	                    restored += got;
583	                    nonempty = reg.iter().any(|&w| w > 0);
584	                    sw!(out, "   {:>3} {}  fuse restores {}", step, g, got);
585	                }
586	            }
587	            Token16_3::Arev | Token16_3::Vinit => {
588	                let lost: u32 = reg.iter().sum();
589	                let banked: u32 = frames.iter().map(|f| f.iter().sum::<u32>()).sum();
590	                cleared += lost;
591	                reg = [0; 4];
592	                if matches!(t, Token16_3::Vinit) { frames.clear(); }
593	                nonempty = false;
594	                sw!(out, "   {:>3} {}  CLEAR loses {}   ({} banked in frames)",
595	                          step, g, lost, banked);
596	            }
597	            Token16_3::Afwd | Token16_3::Imscrib => {
598	                if !nonempty {
599	                    seeded += 1;
600	                    nonempty = true;
601	                    sw!(out, "   {:>3} {}  SEED T into an empty register, no weight", step, g);
602	                }
603	            }
604	            Token16_3::Ifix => { fixed = true; }
605	            _ => {
606	                // The evaluators are the only depositors: EVALT touches T,
607	                // EVALF touches F, EVALI touches t and f together, which is
608	                // why the constructive pair is never seen split.
609	                let touched: &[usize] = match t {
610	                    Token16_3::Evalt => &[0],
611	                    Token16_3::Evalf => &[1],
612	                    Token16_3::Evali => &[2, 3],
613	                    _ => &[],
614	                };
615	                if !touched.is_empty() {
616	                    let mut names = String::new();
617	                    for &j in touched {
618	                        reg[j] += 1;
619	                        if let Some(f) = frames.last_mut() { f[j] += 1; }
620	                        if !names.is_empty() { names.push('+'); }
621	                        names.push_str(NAMES[j]);
622	                    }
623	                    deposits += 1;
624	                    nonempty = true;
625	                    sw!(out, "   {:>3} {}  deposit {}   into depth {}",
626	                              step, g, names, frames.len());
627	                }
628	            }
629	        }
630	    }
631	
632	    let mut surv = String::new();
633	    for j in 0..4 {
634	        if reg[j] > 0 {
635	            if !surv.is_empty() { surv.push_str(", "); }
636	            surv.push_str(&format!("{}×{}", NAMES[j], reg[j]));
637	        }
638	    }
639	    let stranded: u32 = frames.iter().map(|f| f.iter().sum::<u32>()).sum();
640	    sw!(out, "");
641	    sw!(out, "  final    : {}", run_word_register(&steps));
642	    sw!(out, "  surviving: {}", if surv.is_empty() { "none" } else { &surv });
643	    sw!(out, "  deposits {}  cleared {}  restored {}  seeded {}  inert {}",
644	              deposits, cleared, restored, seeded, inert);
645	    if stranded > 0 {
646	        sw!(out, "  stranded in frames never fused: {}", stranded);
647	    }
648	    out
649	}
650

